WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_trv_seg_turn'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '折返变速', 'kp-trv-seg-turn', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "折返变速"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "走了一段发现忘带东西，折返拿完再走，期间速度可能变化。极其容易漏算路程。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“小明离家 5 公里时发现忘带手机，立刻原路返回，拿到手机后再出发。折返时速度提升了 20%。已知家到公司总共 15 公里……”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "最容易死的地方：折返意味着他不仅多走了一个回去的 5 公里，还多走了一个重新出发的 5 公里！总路程平白无故多出了 10 公里！"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[画出一条横线标出总长] --> B[用箭头画出小明先走5公里, 又退回起点的轨迹]\nB --> C[这多出的往返距离 = 2 × 折返点距离]\nC --> D[根据各段不同的速度, 分段计算时间]\nD --> E[累加所有段的时间得出总时长]"}}]}$$ AS jsonb), NULL, '折返变速的核心考点与实战推导。', category_node.id, CAST('["数量关系", "行程问题", "折返变速"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_trv_seg_turn", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
